function openCity(){showDialog('Cidade e momento',`${selectField('city-select','Cidade que você quer consultar',CITY_NAMES,state.city)}<p class="form-note">Sua cidade atual é <b>${esc(state.homeCity)}</b>. Nas outras cidades você consulta conteúdo sem publicar.</p>${selectField('moment-select','Seu momento',[['moro','Moro na cidade'],['chegando','Estou chegando'],['saindo','Estou saindo']],state.mode)}<div class="form-grid"><label class="field-label">Data de chegada<input id="arrival-date" type="date" value="${state.arrival}" min="${dateISO()}"></label><label class="field-label">Data da saída<input id="leave-date" type="date" value="${state.leaveDate}" min="${dateISO()}"></label><div class="full">${selectField('destination-select','Destino',CITY_NAMES.filter(c=>c!==state.homeCity),state.dest)}</div></div>`,`${btn('Cancelar','close-dialog','','text')}${btn('Aplicar','apply-city','','filled')}`);}
function openSettings(){showDialog('Configurações',`<div class="settings-section">${field('profile-name','Seu nome',state.profile.name,'required maxlength="80"')}${selectField('appearance-select','Aparência',[['auto','Automática'],['light','Clara'],['dark','Escura']],state.prefs.appearance)}<div class="choice"><span class="txt"><b>Mostrar meu bairro</b><small>Você pode informar só a cidade.</small></span><md-switch id="privacy-hood" ${state.prefs.showHood?'selected':''} aria-label="Mostrar meu bairro"></md-switch></div><div class="choice"><span class="txt"><b>Convites de família</b><small>Permitir criar convites no seu perfil.</small></span><md-switch id="privacy-family" ${state.prefs.familyOnly?'selected':''} aria-label="Permitir convites de família"></md-switch></div><p class="form-note">Dados de exemplo e alterações ficam neste dispositivo. Verificação de identidade, envio de avisos e cobrança estão no modo teste.</p></div>`,`${btn('Cancelar','close-dialog','','text')}${btn('Salvar','save-settings','','filled')}`);}
function openPrototype(){const official=['md-filled-button','md-outlined-text-field','md-dialog','md-select-option','md-switch','md-filter-chip','md-primary-tab'].every(n=>!!customElements.get(n));showDialog('Controles do protótipo',`<p class="form-note">Dados fictícios para testar as jornadas. Você pode publicar e editar exemplos; nenhuma mensagem é enviada para pessoas reais.</p><div class="choice">${icon(official?'check_circle':'error')}<span class="txt"><b>Material Web oficial · ${esc(MATERIAL_VERSION)}</b><small>${official?'Componentes oficiais carregados e incorporados ao HTML.':'Falha ao carregar os componentes.'}</small></span></div>${selectField('prototype-stage','Estágio da cidade',[['live','Cidade ativa'],['seed','Cidade começando']],state.stage)}${field('prototype-incoming','Famílias com transferência declarada',state.incoming,'type="number" min="0" max="10000"')}<div class="choice"><span class="txt"><b>Verificação de teste</b><small>Controle de leitura e publicação.</small></span><md-switch id="verified-test" ${state.profile.verified?'selected':''} aria-label="Perfil de teste verificado"></md-switch></div><div class="stack">${btn('Ver o cadastro','onboarding','','outlined','verified_user')}${btn('Simular resposta a uma pergunta','simulate-answer','','outlined','forum')}${btn('Simular resposta na conversa','simulate-message','','outlined','chat_bubble')}${btn('Simular decisão do moderador','simulate-moderation','','outlined','shield_person')}</div><p class="form-note">As respostas de exemplo usam o assunto da pergunta. Se não houver uma indicação relacionada, o protótipo não inventa uma resposta.</p>`,`${btn('Recomeçar do zero','reset-prototype','','text')}${btn('Aplicar','apply-prototype','','filled')}`,'prototype');}
